FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state        : INT := 0;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    prevObstacle : BOOL := FALSE;
    prevMotorUp  : BOOL := FALSE;
    prevMotorDown: BOOL := FALSE;
    prevErrorFlag: BOOL := FALSE;
    edgeOpen     : BOOL;
    edgeClose    : BOOL;
    edgeBoth     : BOOL;
END_VAR

// Constants for readability
// IDLE = 0, OPENING = 1, CLOSING = 2, FAULT = 3
// They are implicit via state values.

 // Edge detection
edgeOpen  := openBtn AND NOT prevOpenBtn;
edgeClose := closeBtn AND NOT prevCloseBtn;
edgeBoth  := (openBtn AND closeBtn) AND NOT (prevOpenBtn AND prevCloseBtn);

 // Default outputs (overridden as needed)
motorUp   := FALSE;
motorDown := FALSE;
errorFlag := FALSE;

 // State machine
CASE state OF
    0: // IDLE
        IF obstacle THEN
            // Rule 3: immediate fault
            errorFlag := TRUE;
            state := 3; // FAULT
        ELSE
            // Check start conditions
            IF edgeOpen AND NOT closeBtn AND NOT openLimit THEN
                motorUp := TRUE;
                state := 1; // OPENING
            ELSIF edgeClose AND NOT openBtn AND NOT closeLimit THEN
                motorDown := TRUE;
                state := 2; // CLOSING
            ELSE
                state := 0; // remain IDLE
            END_IF
        END_IF

    1: // OPENING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF openLimit THEN
            motorUp := FALSE;
            state := 0; // IDLE
        ELSE
            motorUp := TRUE;
            state := 1; // remain OPENING
        END_IF

    2: // CLOSING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            motorDown := TRUE;
            state := 2; // remain CLOSING
        END_IF

    3: // FAULT
        // Reset only when previously in fault, no obstacle, and both buttons pressed (risingBoth)
        IF prevErrorFlag AND NOT obstacle AND edgeBoth THEN
            errorFlag := FALSE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            errorFlag := TRUE; // remain latched
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3;
        END_IF

END_CASE

 // Update previous values for next scan
prevOpenBtn   := openBtn;
prevCloseBtn  := closeBtn;
prevObstacle  := obstacle;
prevMotorUp   := motorUp;
prevMotorDown := motorDown;
prevErrorFlag := errorFlag;

END_FUNCTION_BLOCK
```

