    1: // OPENING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF openLimit THEN
            motorUp := FALSE;
            state := 0; // IDLE
        ELSE
            motorUp := TRUE;
            state := 1; // remain OPENING
        END_IF

    2: // CLOSING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            motorDown := TRUE;
            state := 2; // remain CLOSING
        END_IF

    3: // FAULT
        // Reset only when previously in fault, no obstacle, and both buttons pressed (risingBoth)
        IF prevErrorFlag AND NOT obstacle AND edgeBoth THEN
            errorFlag := FALSE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            errorFlag := TRUE; // remain latched
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3;
        END_IF

END_CASE

// Update previous values for next scan
prevOpenBtn   := openBtn;
prevCloseBtn  := closeBtn;
prevObstacle  := obstacle;
prevMotorUp   := motorUp;
prevMotorDown := motorDown;
prevErrorFlag := errorFlag;

END_FUNCTION_BLOCK
```

