VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state        : INT := 0;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    prevObstacle : BOOL := FALSE;
    prevMotorUp  : BOOL := FALSE;
    prevMotorDown: BOOL := FALSE;
    prevErrorFlag: BOOL := FALSE;
    edgeOpen     : BOOL;
    edgeClose    : BOOL;
    edgeBoth     : BOOL;
END_VAR

// Constants for readability
