                motorUp := TRUE;
                state := 1; // OPENING
            ELSIF edgeClose AND NOT openBtn AND NOT closeLimit THEN
                motorDown := TRUE;
                state := 2; // CLOSING
            ELSE
                state := 0; // remain IDLE
            END_IF
        END_IF

    1: // OPENING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF openLimit THEN
            motorUp := FALSE;
            state := 0; // IDLE
        ELSE
            motorUp := TRUE;
            state := 1; // remain OPENING
        END_IF

    2: // CLOSING
        IF obstacle THEN
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3; // FAULT
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            motorDown := TRUE;
            state := 2; // remain CLOSING
        END_IF

    3: // FAULT
