            motorUp   := FALSE;
            motorDown := FALSE;
            state := 0; // IDLE
        ELSE
            errorFlag := TRUE; // remain latched
            motorUp   := FALSE;
            motorDown := FALSE;
            state := 3;
        END_IF

END_CASE

